CREATE TABLE chunks (
    id          SERIAL PRIMARY KEY,
    document_id INTEGER REFERENCES documents(id) ON DELETE CASCADE,
    position    INTEGER NOT NULL,       -- volgorde binnen het document
    page        INTEGER,                -- paginanummer, handig voor citaties
    content     TEXT NOT NULL,
    embedding   vector(1536) NOT NULL   -- lengte = dimensie van je embedding-model
);

-- HNSW-index: snel en benaderend (approximate nearest neighbour)
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops);

def chunk_text(text: str, size: int = 800, overlap: int = 150) -> list[str]:
    """Knip tekst in stukken van size tekens die overlap tekens overlappen."""
    chunks, start = [], 0
    while start < len(text):
        chunks.append(text[start:start + size])
        start += size - overlap
    return chunks

