import re

MAX_CHARS = 2000
VERDACHT = ["ignore previous instructions", "negeer alle eerdere instructies"]

def check_question(text: str) -> str:
    if len(text) > MAX_CHARS:
        raise ValueError("vraag is te lang")
    return text.strip()

def clean_chunk(text: str) -> str:
    for zin in VERDACHT:
        text = re.sub(re.escape(zin), "[verwijderd]", text, flags=re.IGNORECASE)
    return text

