import json
import pytest
from app.rag import answer

with open("evals/cases.json", encoding="utf-8") as f:
    CASES = json.load(f)

@pytest.mark.slow
@pytest.mark.parametrize("case", CASES, ids=[c["question"][:40] for c in CASES])
def test_rag_case(db_session, case):
    result = answer(db_session, case["question"])
    if case["expected_source"]:
        titles = [s["title"] for s in result["sources"]]
        assert case["expected_source"] in titles, "verkeerde retrieval"
    for phrase in case["must_contain"]:
        assert phrase.lower() in result["answer"].lower(), f"mist: {phrase}"

def recall_at_k(results: dict[str, list[int]], labels: dict[str, int], k: int) -> float:
    hits = sum(1 for vraag, juiste in labels.items() if juiste in results[vraag][:k])
    return hits / len(labels)

